const $=id=>document.getElementById(id), esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])), fmt=(x,n=0)=>Number.isFinite(x)?x.toLocaleString('ko-KR',{maximumFractionDigits:n}):'—';
const defaults={...COST_DEFAULTS,project:'',notes:'',parcels:[],road:'',roadMin:'',house:'',houseMin:200,slope:'',slopeMax:'',aspect:'',permit:'unknown',ordinance:'',evidence:'',gridAvailable:'',gridSource:'',gridDate:'',gridAc:100,usable:100,density:7,module:650,moduleLength:2382,moduleWidth:1134,rowGap:1.32,dcac:1.15,capLimit:0,yield:1250,terrainLoss:0,years:20,smp:110,rec:70000,weight:1,epc:90,landUnitPrice:0,landCost:0,extra:0,connection:0,opex:2,rent:0,inflation:2,degrade:.5,discount:6,debt:60,interest:5,tenor:15,replaceYear:12,replaceCost:0,salvage:0};
let state=structuredClone(defaults),rows=[],lastCalc;
const review=[];
const design=[['moduleLength','모듈 세로 길이 (mm · 기본 2382)'],['moduleWidth','모듈 가로 너비 (mm · 기본 1134)'],['module','모듈 출력 (Wp · 기본 650)'],['usable','모듈 배치 대상 면적 비율 (%)'],['rowGap','모듈 행 사이 빈 간격 (m · 기본 1.32)'],['dcac','DC / AC 비율'],['capLimit','설계 용량 상한 (kWp, 0=없음)'],['yield','기준 연간 발전량 (kWh/kWp)'],['terrainLoss','향·음영·출력제어 추가 손실 (%)']];
